  "implementation": "def solve(case):
    import json

    # Validate required fields
    for key in ('nodes', 'core_distance', 'distances'):
        if key not in case:
            raise ValueError(f"Missing required field: {key}")

    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Ensure all nodes exist in core_distance and distances cover all needed? Not strictly required
    # Build set of nodes
    node_set = set(nodes)
    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"Node {node} missing from core_distance")

    # Build edge list with mutual reachability weight
    edges = []
    for a, b, d in distances:
        if a not in node_set or b not in node_set:
            raise ValueError(f"Edge references unknown node")
        core_a = core_distance[a]
        core_b = core_distance[b]
        weight = max(core_a, core_b, d)
        # Canonicalize: order endpoints lexicographically (string)
        if a <= b:
            u, v = a, b
        else:
            u, v = b, a
        edges.append((weight, u, v))

    # Sort edges by (weight, u, v)
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n = len(nodes)
    target = n - 1

    for weight, u, v in edges:
        if len(mst_edges) == target:
            break
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight

    if len(mst_edges) != target:
        raise ValueError("Graph is not connected; cannot form MST")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
